32	    retry: false,
33	  });
34	
35	  const onNextPage = useCallback(() => {
36	    previousPageTokens.current.push(currentPageToken);
37	    setCurrentPageToken(queryResult.data?.next_page_token);
38	  }, [queryResult.data?.next_page_token, currentPageToken]);
39	
40	  const onPreviousPage = useCallback(() => {
41	    const previousPageToken = previousPageTokens.current.pop();
42	    setCurrentPageToken(previousPageToken);
43	  }, []);
