47	    error: queryResult.error ?? undefined,
48	    isLoading: queryResult.isLoading,
49	    hasNextPage: queryResult.data?.next_page_token !== undefined,
50	    hasPreviousPage: Boolean(currentPageToken),
51	    onNextPage,
52	    onPreviousPage,
53	    refetch: queryResult.refetch,
54	  };
55	};
