6	type UpdateContentPayload = {
7	  promptName: string;
8	  promptType: typeof PROMPT_TYPE_CHAT | typeof PROMPT_TYPE_TEXT;
9	  createPromptEntity?: boolean;
10	  content: string;
11	  commitMessage?: string;
12	  tags: { key: string; value: string }[];
13	  promptTags?: { key: string; value: string }[];
14	  responseFormatJson?: string;
15	};
