17	export const useCreateRegisteredPromptMutation = () => {
18	  const updateMutation = useMutation<{ version: string }, Error, UpdateContentPayload>({
19	    mutationFn: async ({
20	      promptName,
21	      promptType,
22	      createPromptEntity,
23	      content,
24	      commitMessage,
25	      tags,
26	      promptTags = [],
27	      responseFormatJson,
28	    }) => {
29	      if (createPromptEntity) {
30	        await RegisteredPromptsApi.createRegisteredPrompt(promptName, promptTags);
31	      }
32	
33	      const responseFormatTag = responseFormatJson ? [{ key: RESPONSE_FORMAT_TAG_KEY, value: responseFormatJson }] : [];
34	
35	      const version = await RegisteredPromptsApi.createRegisteredPromptVersion(
36	        promptName,
37	        [
38	          { key: REGISTERED_PROMPT_CONTENT_TAG_KEY, value: content },
39	          { key: PROMPT_TYPE_TAG_KEY, value: promptType },
40	          ...tags,
41	          ...responseFormatTag,
42	        ],
43	        commitMessage,
44	      );
45	
46	      const newVersionNumber = version?.model_version?.version;
47	      if (!newVersionNumber) {
48	        throw new Error('Failed to create a new prompt version');
49	      }
50	      return { version: newVersionNumber };
51	    },
52	  });
53	
54	  return updateMutation;
55	};
